1	import { useEffect, useRef, useState } from "react";
2	import { useLocation, useParams } from "wouter";
3	import { useQueryClient } from "@tanstack/react-query";
4	import {
5	  useCreateCourt, useUpdateCourt, customFetch, getListCourtsQueryKey,
6	  useGetCourt, getGetCourtQueryKey,
7	} from "@workspace/api-client-react";
8	import { OwnerLayout } from "@/components/owner-layout";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
12	import { Skeleton } from "@/components/ui/skeleton";
13	import { Textarea } from "@/components/ui/textarea";
14	import { Checkbox } from "@/components/ui/checkbox";
15	import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
16	import { Label } from "@/components/ui/label";
17	import { useToast } from "@/hooks/use-toast";
18	import { useForm } from "react-hook-form";
19	import { zodResolver } from "@hookform/resolvers/zod";
20	import { z } from "zod";
21	import {
22	  ChevronLeft, Euro, Clock3, Lightbulb, ShoppingBag, ShowerHead, DoorOpen,
23	  Droplets, Car, Bath, Wifi, Coffee, HeartPulse, Thermometer, Wind, Lock,
24	  Flame, Plus, X, Images, Upload, Loader2, MapPin, Trash2,
25	} from "lucide-react";
26	import { CourtImageUpload } from "@/components/court-image-upload";
27	import { SPORT_LABELS } from "@/components/sport-icon";
28	
29	const BASE_URL = import.meta.env.BASE_URL.replace(/\/$/, "");
30	const API_URL = `${BASE_URL}/api`;
31	const MAX_GALLERY_PHOTOS = 3;
32	
33	const STANDARD_AMENITIES = [
34	  { id: "floodlights", label: "Prožektoriai", icon: Lightbulb },
35	  { id: "showers", label: "Dušai", icon: ShowerHead },
36	  { id: "changing_rooms", label: "Persirengimo kambariai", icon: DoorOpen },
37	  { id: "water_station", label: "Vandens stotis", icon: Droplets },
38	  { id: "parking", label: "Parkavimas", icon: Car },
39	  { id: "toilets", label: "Tualetai", icon: Bath },
40	  { id: "wifi", label: "Wi-Fi", icon: Wifi },
41	  { id: "cafe", label: "Kavinė / Baras", icon: Coffee },
42	  { id: "first_aid", label: "Pirmoji pagalba", icon: HeartPulse },
43	  { id: "heating", label: "Šildymas", icon: Thermometer },
44	  { id: "air_conditioning", label: "Oro kondicionierius", icon: Wind },
45	  { id: "lockers", label: "Spintelės", icon: Lock },
46	  { id: "sauna", label: "Pirtis", icon: Flame },
47	] as const;
48	
49	interface RentableItem { name: string; pricePerSlot: number; stock: number; }
50	
51	type WorkingHourDay = { open: string; close: string; closed: boolean };
52	type WorkingHoursMap = Record<string, WorkingHourDay>;
53	
54	// Court working hours use numeric day-of-week keys ("0"=Sunday … "6"=Saturday).
55	// Defaults must match the facility's DEFAULT_HOURS in settings.tsx so the
56	// inheritance preview shows the same values when the facility has no saved
57	// businessHours yet.
58	function defaultWorkingHours(): WorkingHoursMap {
59	  return {
60	    "0": { open: "09:00", close: "20:00", closed: false }, // Sunday
61	    "1": { open: "08:00", close: "22:00", closed: false },
62	    "2": { open: "08:00", close: "22:00", closed: false },
63	    "3": { open: "08:00", close: "22:00", closed: false },
64	    "4": { open: "08:00", close: "22:00", closed: false },
65	    "5": { open: "08:00", close: "22:00", closed: false },
66	    "6": { open: "09:00", close: "20:00", closed: false }, // Saturday
67	  };
68	}
69	
70	// Facility business hours use named keys ("monday"…"sunday"). Convert → court format.
71	const FACILITY_DAY_TO_NUM: Record<string, string> = {
72	  sunday: "0", monday: "1", tuesday: "2", wednesday: "3",
73	  thursday: "4", friday: "5", saturday: "6",
74	};
75	function facilityHoursToCourtFormat(jsonStr: string | null | undefined): WorkingHoursMap | null {
76	  if (!jsonStr) return null;
77	  try {
78	    const parsed = JSON.parse(jsonStr) as Record<string, WorkingHourDay>;
79	    const out: WorkingHoursMap = {};
80	    for (const [k, v] of Object.entries(parsed)) {
81	      const num = FACILITY_DAY_TO_NUM[k.toLowerCase()];
82	      if (num && v && typeof v === "object") {
83	        out[num] = { open: v.open ?? "08:00", close: v.close ?? "22:00", closed: !!v.closed };
84	      }
85	    }
86	    // Fill in any missing days
87	    for (const d of ["0", "1", "2", "3", "4", "5", "6"]) {
88	      if (!out[d]) out[d] = { open: "08:00", close: "22:00", closed: false };
89	    }
90	    return out;
91	  } catch { return null; }
92	}
93	
94	const HOUR_OPTIONS: string[] = [];
95	for (let h = 0; h <= 23; h++) {
96	  for (const m of [0, 30]) {
97	    HOUR_OPTIONS.push(`${String(h).padStart(2, "0")}:${m === 0 ? "00" : "30"}`);
98	  }
99	}
100	const dayNames: Record<string, string> = {
101	  "0": "Sekmadienis", "1": "Pirmadienis", "2": "Antradienis", "3": "Trečiadienis",
102	  "4": "Ketvirtadienis", "5": "Penktadienis", "6": "Šeštadienis",
103	};
104	
105	const courtSchema = z.object({
106	  name: z.string().min(2, "Pavadinimas privalomas"),
107	  type: z.enum(["tennis", "basketball", "padel", "football", "badminton", "squash", "table_tennis", "golf", "snooker", "bowling"]),
108	  description: z.string().optional(),
109	  pricePerHour: z.coerce.number().min(1),
110	  imageUrl: z.string().optional(),
111	  isIndoor: z.boolean().default(false),
112	  maxPlayers: z.coerce.number().min(2),
113	  amenities: z.array(z.string()).default([]),
114	  surface: z.string().optional(),
115	  surfaceSpeed: z.string().optional(),
116	  surfaceBounce: z.string().optional(),
117	  hasSmartLock: z.boolean().default(false),
118	  accessInstructions: z.string().optional(),
119	});
120	type CourtFormValues = z.infer<typeof courtSchema>;
121	
122	interface FacilityData {
123	  id: number;
124	  name: string;
125	  ownerUserId?: string | null;
126	  address?: string | null;
127	  city?: string | null;
128	  phone?: string | null;
129	  email?: string | null;
130	  businessHours?: string | null;
131	  websiteUrl?: string | null;
132	  socialFacebook?: string | null;
133	  socialInstagram?: string | null;
134	  socialWhatsapp?: string | null;
135	  verificationStatus?: string | null;
136	}
137	
138	const TABS = [
139	  { id: "info", label: "Pagrindai" },
140	  { id: "schedule", label: "Grafikas" },
141	  { id: "amenities", label: "Patogumai" },
142	  { id: "media", label: "Medija" },
143	  { id: "contact", label: "Kontaktai" },
144	] as const;
145	type TabId = typeof TABS[number]["id"];
146	
147	export default function CourtCreatePage() {
148	  const { toast } = useToast();
149	  const [, navigate] = useLocation();
150	  const params = useParams();
151	  const queryClient = useQueryClient();
152	  const createCourt = useCreateCourt();
153	  const updateCourt = useUpdateCourt();
154	  const facilityId = Number(params.id ?? 0);
155	  const editingCourtId = params.courtId ? Number(params.courtId) : null;
156	  const isEdit = editingCourtId !== null;
157	  const [facility, setFacility] = useState<FacilityData | null>(null);
158	  const [loading, setLoading] = useState(true);
159	  const [hydrated, setHydrated] = useState(false);
160	
161	  const [formTab, setFormTab] = useState<TabId>("info");
162	
163	  // Working hours: inherit from facility by default; override flag = use court-specific hours
164	  const [overrideHours, setOverrideHours] = useState(false);
165	  const [workingHoursState, setWorkingHoursState] = useState<WorkingHoursMap>(defaultWorkingHours());
166	
167	  // Contacts: inherit from facility by default; override flag = use court-specific contacts
168	  const [overrideContacts, setOverrideContacts] = useState(false);
169	  const [courtPhone, setCourtPhone] = useState("");
170	  const [courtFacebook, setCourtFacebook] = useState("");
171	  const [courtInstagram, setCourtInstagram] = useState("");
172	  const [courtWhatsapp, setCourtWhatsapp] = useState("");
173	  const [courtWebsite, setCourtWebsite] = useState("");
174	
175	  // Photo gallery: local file buffer uploaded after court creation
176	  const [galleryFiles, setGalleryFiles] = useState<File[]>([]);
177	  const [galleryPreviews, setGalleryPreviews] = useState<string[]>([]);
178	  const galleryInputRef = useRef<HTMLInputElement>(null);
179	  const [uploadingGallery, setUploadingGallery] = useState(false);
180	  const [galleryProgress, setGalleryProgress] = useState<{ current: number; total: number } | null>(null);
181	
182	  const [rentableItems, setRentableItems] = useState<RentableItem[]>([]);
183	  const [newItemName, setNewItemName] = useState("");
184	  const [newItemPrice, setNewItemPrice] = useState("");
185	  const [newItemStock, setNewItemStock] = useState("");
186	  const [amenityPhotos, setAmenityPhotos] = useState<Record<string, string>>({});
187	  const [uploadingAmenity, setUploadingAmenity] = useState<string | null>(null);
188	
189	  useEffect(() => {
190	    if (!facilityId) return;
191	    customFetch<FacilityData>(`${API_URL}/facilities/${facilityId}`)
192	      .then((data) => {
193	        setFacility(data);
194	        // Pre-fill working hours from facility's businessHours
195	        const fromFacility = facilityHoursToCourtFormat(data.businessHours);
196	        if (fromFacility) setWorkingHoursState(fromFacility);
197	        // Pre-fill contacts
198	        setCourtPhone(data.phone ?? "");
199	        setCourtFacebook(data.socialFacebook ?? "");
200	        setCourtInstagram(data.socialInstagram ?? "");
201	        setCourtWhatsapp(data.socialWhatsapp ?? "");
202	        setCourtWebsite(data.websiteUrl ?? "");
203	      })
204	      .finally(() => setLoading(false));
205	  }, [facilityId]);
206	
207	  // Cleanup blob URLs on unmount / change
208	  useEffect(() => {
209	    return () => { galleryPreviews.forEach((u) => URL.revokeObjectURL(u)); };
210	  }, [galleryPreviews]);
211	
212	  const form = useForm<CourtFormValues>({
213	    resolver: zodResolver(courtSchema),
214	    defaultValues: {
215	      name: "",
216	      type: "tennis",
217	      description: "",
218	      pricePerHour: 20,
219	      imageUrl: "",
220	      isIndoor: false,
221	      maxPlayers: 4,
222	      amenities: [],
223	      surface: "",
224	      surfaceSpeed: "",
225	      surfaceBounce: "",
226	      hasSmartLock: false,
227	      accessInstructions: "",
228	    },
229	  });
230	
231	  // Edit-mode: load existing court + pricing and hydrate form/state once.
232	  const { data: editingCourt } = useGetCourt(editingCourtId ?? 0, {
233	    query: {
234	      queryKey: getGetCourtQueryKey(editingCourtId ?? 0),
235	      enabled: isEdit && editingCourtId !== null && editingCourtId > 0,
236	    },
237	  });
238	  useEffect(() => {
239	    if (!isEdit || hydrated || !editingCourt) return;
240	    const c = editingCourt as any;
241	    form.reset({
242	      name: c.name ?? "",
243	      type: c.type ?? "tennis",
244	      description: c.description ?? "",
245	      pricePerHour: Number(c.pricePerHour ?? 20),
246	      imageUrl: c.imageUrl ?? "",
247	      isIndoor: !!c.isIndoor,
248	      maxPlayers: Number(c.maxPlayers ?? 4),
249	      amenities: Array.isArray(c.amenities) ? c.amenities : [],
250	      surface: c.surface ?? "",
251	      surfaceSpeed: c.surfaceSpeed ?? "",
252	      surfaceBounce: c.surfaceBounce ?? "",
253	      hasSmartLock: !!c.hasSmartLock,
254	      accessInstructions: c.accessInstructions ?? "",
255	    });
256	    if (c.workingHours) {
257	      try {
258	        const parsed = JSON.parse(c.workingHours);
259	        setWorkingHoursState({ ...defaultWorkingHours(), ...parsed });
260	        setOverrideHours(true);
261	      } catch { /* keep facility-inherited defaults */ }
262	    }
263	    if (c.rentableItems) {
264	      try {
265	        const raw: any[] = JSON.parse(c.rentableItems);
266	        setRentableItems(raw.map((r) => ({
267	          name: r.name,
268	          pricePerSlot: r.pricePerSlot ?? r.pricePerBooking ?? 0,
269	          stock: r.stock ?? 1,
270	        })));
271	      } catch { /* ignore */ }
272	    }
273	    if (c.amenityPhotos) {
274	      try {
275	        const photos = JSON.parse(c.amenityPhotos);
276	        if (typeof photos === "object" && photos !== null) setAmenityPhotos(photos);
277	      } catch { /* ignore */ }
278	    }
279	    // Contact override: if any court-specific contact value differs from facility, enable override
280	    const facPhone = facility?.phone ?? "";
281	    const facFb = facility?.socialFacebook ?? "";
282	    const facIg = facility?.socialInstagram ?? "";
283	    const facWa = facility?.socialWhatsapp ?? "";
284	    const facWeb = facility?.websiteUrl ?? "";
285	    const cPhone = c.phone ?? "";
286	    const cFb = c.socialFacebook ?? "";
287	    const cIg = c.socialInstagram ?? "";
288	    const cWa = c.socialWhatsapp ?? "";
289	    const cWeb = c.socialWebsite ?? "";
290	    const hasOverride =
291	      (cPhone && cPhone !== facPhone) || (cFb && cFb !== facFb) ||
292	      (cIg && cIg !== facIg) || (cWa && cWa !== facWa) || (cWeb && cWeb !== facWeb);
293	    if (hasOverride) {
294	      setOverrideContacts(true);
295	      setCourtPhone(cPhone); setCourtFacebook(cFb);
296	      setCourtInstagram(cIg); setCourtWhatsapp(cWa); setCourtWebsite(cWeb);
297	    }
298	    setHydrated(true);
299	  }, [isEdit, hydrated, editingCourt, facility, form]);
300	
301	  const handleAmenityPhotoUpload = async (amenityId: string, file: File) => {
302	    setUploadingAmenity(amenityId);
303	    try {
304	      const fd = new FormData();
305	      fd.append("image", file);
306	      const resp = await fetch(`${BASE_URL}/api/upload/amenity-photo`, { method: "POST", body: fd });
307	      if (!resp.ok) throw new Error("Upload failed");
308	      const { url } = await resp.json();
309	      setAmenityPhotos((prev) => ({ ...prev, [amenityId]: url }));
310	      toast({ title: "Nuotrauka įkelta" });
311	    } catch {
312	      toast({ title: "Klaida", variant: "destructive" });
313	    } finally {
314	      setUploadingAmenity(null);
315	    }
316	  };
317	
318	  const handleAddGalleryFiles = (files: FileList) => {
319	    const remaining = MAX_GALLERY_PHOTOS - galleryFiles.length;
320	    if (remaining <= 0) {
321	      toast({ title: "Pasiektas limitas", description: `Maks. ${MAX_GALLERY_PHOTOS} nuotraukos.`, variant: "destructive" });
322	      return;
323	    }
324	    const toAdd = Array.from(files).slice(0, remaining);
325	    if (toAdd.length < files.length) {
326	      toast({ title: `Pridedamos tik ${toAdd.length} nuotraukos` });
327	    }
328	    const newPreviews = toAdd.map((f) => URL.createObjectURL(f));
329	    setGalleryFiles((p) => [...p, ...toAdd]);
330	    setGalleryPreviews((p) => [...p, ...newPreviews]);
331	  };
332	  const handleRemoveGallery = (idx: number) => {
333	    URL.revokeObjectURL(galleryPreviews[idx]);
334	    setGalleryFiles((p) => p.filter((_, i) => i !== idx));
335	    setGalleryPreviews((p) => p.filter((_, i) => i !== idx));
336	  };
337	
338	  // Map form field name → tab id (for routing validation errors to the right tab)
339	  const FIELD_TO_TAB: Record<string, TabId> = {
340	    name: "info",
341	    type: "info",
342	    description: "info",
343	    surface: "info",
344	    surfaceSpeed: "info",
345	    surfaceBounce: "info",
346	    pricePerHour: "schedule",
347	    maxPlayers: "amenities",
348	    isIndoor: "amenities",
349	    hasSmartLock: "amenities",
350	    accessInstructions: "amenities",
351	    imageUrl: "media",
352	  };
353	  const FIELD_LABELS: Record<string, string> = {
354	    name: "Aikštelės pavadinimas",
355	    type: "Sporto šaka",
356	    pricePerHour: "Numatytoji kaina",
357	    maxPlayers: "Maks. žaidėjai",
358	    description: "Aprašymas",
359	    imageUrl: "Pagrindinė nuotrauka",
360	    surface: "Dangos tipas",
361	    accessInstructions: "Prieigos instrukcijos",
362	  };
363	
364	  const onInvalid = (errors: Record<string, { message?: string } | undefined>) => {
365	    const fields = Object.keys(errors);
366	    if (fields.length === 0) return;
367	    // Switch to the first tab that has an error (in tab order)
368	    const tabOrder = TABS.map((t) => t.id) as TabId[];
369	    let firstTab: TabId | null = null;
370	    for (const tid of tabOrder) {
371	      if (fields.some((f) => FIELD_TO_TAB[f] === tid)) { firstTab = tid; break; }
372	    }
373	    if (firstTab) setFormTab(firstTab);
374	    const labels = fields.map((f) => FIELD_LABELS[f] ?? f).join(", ");
375	    toast({
376	      title: "Užpildykite privalomus laukus",
377	      description: `Trūksta arba neteisingi: ${labels}`,
378	      variant: "destructive",
379	    });
380	  };
381	
382	  const buildPayload = (data: Partial<CourtFormValues>): Record<string, unknown> => {
383	    const cleanStr = (v: unknown): string | undefined => {
384	      if (typeof v !== "string") return undefined;
385	      const t = v.trim();
386	      return t.length > 0 ? t : undefined;
387	    };
388	    const effPhone     = overrideContacts ? courtPhone     : facility?.phone     ?? "";
389	    const effFacebook  = overrideContacts ? courtFacebook  : facility?.socialFacebook  ?? "";
390	    const effInstagram = overrideContacts ? courtInstagram : facility?.socialInstagram ?? "";
391	    const effWhatsapp  = overrideContacts ? courtWhatsapp  : facility?.socialWhatsapp  ?? "";
392	    const effWebsite   = overrideContacts ? courtWebsite   : facility?.websiteUrl      ?? "";
393	    return {
394	      ...data,
395	      facilityId,
396	      rentableItems: rentableItems.length > 0 ? JSON.stringify(rentableItems) : undefined,
397	      workingHours: overrideHours ? JSON.stringify(workingHoursState) : null,
398	      amenityPhotos: Object.keys(amenityPhotos).length > 0 ? JSON.stringify(amenityPhotos) : undefined,
399	      description: cleanStr(data.description),
400	      imageUrl: cleanStr(data.imageUrl),
401	      surface: cleanStr((data as any).surface),
402	      surfaceSpeed: cleanStr((data as any).surfaceSpeed),
403	      surfaceBounce: cleanStr((data as any).surfaceBounce),
404	      hasSmartLock: !!(data as any).hasSmartLock,
405	      accessInstructions: cleanStr((data as any).accessInstructions),
406	      phone: cleanStr(effPhone),
407	      socialFacebook: cleanStr(effFacebook),
408	      socialInstagram: cleanStr(effInstagram),
409	      socialWhatsapp: cleanStr(effWhatsapp),
410	      socialWebsite: cleanStr(effWebsite),
411	    };
412	  };
413	
414	  const [savingDraft, setSavingDraft] = useState(false);
415	  const saveAsDraft = async () => {
416	    const values = form.getValues();
417	    const name = (values.name ?? "").trim();
418	    if (!name) {
419	      setFormTab("info");
420	      form.setError("name", { type: "manual", message: "Įveskite bent pavadinimą juodraščiui" });
421	      toast({
422	        title: "Reikia bent pavadinimo",
423	        description: "Įveskite aikštelės pavadinimą, kad išsaugotumėte juodraštį.",
424	        variant: "destructive",
425	      });
426	      return;
427	    }
428	    setSavingDraft(true);
429	    try {
430	      // Relaxed defaults so the API always accepts the partial draft
431	      const payload = buildPayload({
432	        ...values,
433	        name,
434	        type: values.type ?? "tennis",
435	        pricePerHour: values.pricePerHour && values.pricePerHour >= 1 ? values.pricePerHour : 1,
436	        maxPlayers: values.maxPlayers && values.maxPlayers >= 2 ? values.maxPlayers : 2,
437	        isIndoor: !!values.isIndoor,
438	        amenities: values.amenities ?? [],
439	      });
440	      (payload as any).status = "draft";
441	      await createCourt.mutateAsync({ data: payload as any });
442	      queryClient.invalidateQueries({ queryKey: ["facility-detail", String(facilityId)] });
443	      queryClient.invalidateQueries({ queryKey: ["owner-facilities"] });
444	      toast({ title: "Juodraštis išsaugotas" });
445	      navigate(`/owner/facility/${facilityId}`);
446	    } catch (err) {
447	      const anyErr = err as any;
448	      toast({
449	        title: "Nepavyko išsaugoti juodraščio",
450	        description: anyErr?.data?.error ?? anyErr?.message ?? "Bandykite dar kartą",
451	        variant: "destructive",
452	      });
453	    } finally {
454	      setSavingDraft(false);
455	    }
456	  };
457	
458	  const onSubmit = async (data: CourtFormValues) => {
459	    try {
460	      const payload = buildPayload(data);
461	      let courtIdResult: number;
462	      if (isEdit && editingCourtId) {
463	        await updateCourt.mutateAsync({ id: editingCourtId, data: payload as any });
464	        courtIdResult = editingCourtId;
465	      } else {
466	        const newCourt = await createCourt.mutateAsync({ data: payload as any });
467	        courtIdResult = (newCourt as any).id;
468	      }
469	      const newCourtId = courtIdResult;
470	
471	      // Upload gallery photos sequentially
472	      if (galleryFiles.length > 0) {
473	        setUploadingGallery(true);
474	        setGalleryProgress({ current: 0, total: galleryFiles.length });
475	        try {
476	          for (let i = 0; i < galleryFiles.length; i++) {
477	            setGalleryProgress({ current: i + 1, total: galleryFiles.length });
478	            const fd = new FormData();
479	            fd.append("image", galleryFiles[i]);
480	            const r = await fetch(`${API_URL}/courts/${newCourtId}/photos`, {
481	              method: "POST", body: fd, credentials: "include",
482	            });
483	            if (!r.ok) throw new Error(`Photo upload failed (${r.status})`);
484	          }
485	        } catch (e: any) {
486	          toast({ title: "Galerijos įkėlimas nepavyko", description: e?.message ?? "Bandykite vėliau redaguodami aikštelę", variant: "destructive" });
487	        } finally {
488	          setUploadingGallery(false);
489	          setGalleryProgress(null);
490	        }
491	      }
492	
493	      queryClient.invalidateQueries({
494	        queryKey: getListCourtsQueryKey(facility?.ownerUserId ? { ownerUserId: facility.ownerUserId } : undefined),
495	      });
496	      queryClient.invalidateQueries({ queryKey: ["facility-detail", String(facilityId)] });
497	      queryClient.invalidateQueries({ queryKey: ["owner-facilities"] });
498	      if (isEdit && editingCourtId) {
499	        queryClient.invalidateQueries({ queryKey: getGetCourtQueryKey(editingCourtId) });
500	      }
501	      toast({ title: isEdit ? "Aikštelė atnaujinta" : "Aikštelė sukurta — laukia patvirtinimo" });
