25	async function reverseGeocode(lat: number, lng: number): Promise<Omit<LocationPickerResult, "lat" | "lng">> {
26	  try {
27	    const res = await fetch(
28	      `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`,
29	      { headers: { "Accept-Language": "lt,en" } }
30	    );
31	    if (!res.ok) return {};
32	    const data = await res.json();
33	    const addr = data.address ?? {};
34	    const city = addr.city ?? addr.town ?? addr.village ?? addr.municipality ?? "";
35	    const road = addr.road ?? "";
36	    const houseNumber = addr.house_number ? ` ${addr.house_number}` : "";
37	    const address = road ? `${road}${houseNumber}` : "";
38	    const postcode = addr.postcode ?? "";
39	    return { city, address, postcode };
40	  } catch {
41	    return {};
42	  }
43	}
