45	function extractFromPlaceComponents(
46	  components: google.maps.GeocoderAddressComponent[]
47	): Omit<LocationPickerResult, "lat" | "lng"> {
48	  const get = (type: string) =>
49	    components.find(c => c.types.includes(type))?.long_name ?? "";
50	
51	  const streetNumber = get("street_number");
52	  const route = get("route");
53	  const address = route ? `${route}${streetNumber ? " " + streetNumber : ""}` : "";
54	  const city =
55	    get("locality") ||
56	    get("administrative_area_level_2") ||
57	    get("administrative_area_level_1");
58	  const postcode = get("postal_code");
59	
60	  return { address, city, postcode };
61	}
