328	    res.status(400).json({ error: "Objektas jau laukia patvirtinimo." });
329	    return;
330	  }
331	  if (facility.verificationStatus === "suspended") {
332	    res.status(400).json({ error: "Objektas sustabdytas — kreipkitės į administratorių." });
333	    return;
334	  }
335	
336	  const issues = validateForVerification(facility);
337	  if (issues.length > 0) {
338	    res.status(400).json({
339	      error: "Trūksta privalomų duomenų prieš pateikiant patvirtinimui.",
340	      issues,
341	    });
342	    return;
343	  }
344	
345	  // Owner-level Stripe gate — single source of truth. Live re-check against
346	  // Stripe so a missed webhook can't block the owner indefinitely, and a stale
347	  // cache can't promote past the gate.
348	  const liveResult = await ownerStripeReadyLive(userId);
349	  if (liveResult.error) {
350	    res.status(503).json({
351	      error: "Nepavyko pasiekti Stripe paslaugos. Bandykite dar kartą po kelių sekundžių.",
352	    });
353	    return;
354	  }
355	  if (!liveResult.ready) {
356	    // Sync the cached owner status before refusing so the UI can react.
357	    await db
358	      .update(userProfilesTable)
359	      .set({ stripeAccountStatus: "pending" })
360	      .where(eq(userProfilesTable.userId, userId));
361	    res.status(422).json({
362	      error: "Prijunkite Stripe Connect prieš teikdami objektą patvirtinimui.",
363	      code: "stripe_not_connected",
364	    });
365	    return;
366	  }
367	
368	  // Compare-and-set: only mutate if the row is STILL in the status we read.
369	  const [updated] = await db
370	    .update(facilitiesTable)
371	    .set({
372	      verificationStatus: "pending_verification",
373	      verificationNotes: null,
374	      rejectionReason: null,
375	    })
376	    .where(and(
377	      eq(facilitiesTable.id, id),
378	      eq(facilitiesTable.verificationStatus, facility.verificationStatus),
379	    ))
380	    .returning();
381	
382	  if (!updated) {
383	    res.status(409).json({
384	      error: "Objekto būsena pasikeitė. Atnaujinkite puslapį ir bandykite dar kartą.",
385	    });
386	    return;
387	  }
